description:
Write `spy(impl)` that returns a function which:

- calls `impl` with the same arguments (if `impl` is given) and returns its result;
- records every call: `fn.calls` is an array of argument arrays, and `fn.results` an array of what each call returned;
- has `fn.calledWith(...args)` that is true when some call had exactly those arguments (compared with `===` one by one);
- has `fn.reset()` that clears both arrays.

solution.solution.js:
function spy(impl) {
  const fn = (...args) => {
    fn.calls.push(args);
    const result = impl ? impl(...args) : undefined;
    fn.results.push(result);
    return result;
  };
  fn.calls = [];
  fn.results = [];
  fn.calledWith = (...expected) =>
    fn.calls.some(args => args.length === expected.length && args.every((a, i) => a === expected[i]));
  fn.reset = () => {
    fn.calls = [];
    fn.results = [];
  };
  return fn;
}

unitTests:
test("records calls and results", () => {
  const add = spy((a, b) => a + b);
  checkEq(add(2, 3), 5);
  add(1, 1);
  checkEq(add.calls, [[2, 3], [1, 1]]);
  checkEq(add.results, [5, 2]);
});

test("works without an implementation", () => {
  const log = spy();
  checkEq(log("x"), undefined);
  checkEq(log.calls.length, 1);
});

test("calledWith", () => {
  const send = spy();
  send("ada", "hi");
  check(send.calledWith("ada", "hi"));
  check(!send.calledWith("ada"));
  check(!send.calledWith("bob", "hi"));
});

test("reset", () => {
  const f = spy(() => 1);
  f();
  f.reset();
  checkEq([f.calls, f.results], [[], []]);
});

